<?php
if(PHP_SAPI!=='cli')exit;chdir(dirname(__DIR__));require 'app/Core/DB.php';$db=DB::getInstance();$scope=['76.01','1.03.0.00.0.00.01.0000',2026];$actor='PPK_SYAMSUNAR_20261028';$dir='outputs/ppk-syamsunar-20261028';if(!is_dir($dir))mkdir($dir,0775,true);
$all=$db->query('SELECT * FROM kontrak_neo ORDER BY id')->fetchAll();$officials=$db->query('SELECT * FROM pejabat_tahunan_neo WHERE kd_wilayah=? AND kd_opd=? AND tahun=? AND is_deleted=0',$scope)->fetchAll();file_put_contents($dir.'/before.json',json_encode(['contracts'=>$all,'officials'=>$officials],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
$base=current(array_filter($officials,fn($r)=>$r['jenis_pejabat']==='PPK'&&$r['pegawai_id']==3&&$r['id']!=1));if(!$base)throw new RuntimeException('Missing Syamsunar');$updated=[];
$db->begin();try{
foreach($officials as$p){if($p['jenis_pejabat']!=='PPK'||(int)$p['pegawai_id']===3)continue;
$db->update('pejabat_tahunan_neo',['pegawai_id'=>3,'nama_pegawai'=>'SYAMSUNAR','nip'=>'197503102009031001','nomor_sk'=>'','tanggal_sk'=>null,'keterangan'=>'PPK diubah menjadi Syamsunar sesuai instruksi 28 Oktober 2026; nomor/tanggal SK penugasan baru belum tersedia.','username_update'=>$actor,'tgl_update'=>date('Y-m-d H:i:s')],'WHERE id=?',[$p['id']]);$updated[]=['official_id'=>$p['id'],'subactivity'=>$p['kd_sub_keg'],'ppk'=>'SYAMSUNAR'];}
foreach($all as$c){if($c['kd_wilayah']!==$scope[0]||$c['kd_opd']!==$scope[1]||(int)$c['tahun']!==2026||$c['is_deleted']||$c['ppk_id']||!$c['rekanan_id'])continue;
$p=$db->query('SELECT id FROM pejabat_tahunan_neo WHERE kd_wilayah=? AND kd_opd=? AND tahun=? AND jenis_pejabat="PPK" AND pegawai_id=3 AND kd_sub_keg=? AND is_deleted=0 ORDER BY id DESC LIMIT 1',[...$scope,$c['kd_sub_keg']])->fetch();if(!$p)throw new RuntimeException('Missing PPK assignment');
$db->update('kontrak_neo',['ppk_id'=>$p['id'],'nama_ppk'=>'SYAMSUNAR','username_update'=>$actor,'tgl_update'=>date('Y-m-d H:i:s')],'WHERE id=?',[$c['id']]);$updated[]=['contract_id'=>$c['id'],'ppk_id'=>$p['id']];}
// Provider-less drafts use the same scoped annual assignment when resolved for printing.
foreach($all as$c){if($c['kd_wilayah']!==$scope[0]||$c['kd_opd']!==$scope[1]||(int)$c['tahun']!==2026||$c['is_deleted']||$c['ppk_id']||$c['rekanan_id'])continue;$p=$db->query('SELECT id FROM pejabat_tahunan_neo WHERE kd_wilayah=? AND kd_opd=? AND tahun=? AND jenis_pejabat="PPK" AND pegawai_id=3 AND kd_sub_keg=? AND is_deleted=0',[...$scope,$c['kd_sub_keg']])->fetch();if(!$p){$r=$base;unset($r['id'],$r['tgl_insert'],$r['tgl_update'],$r['username_update']);$r['kd_sub_keg']=$c['kd_sub_keg'];$r['nomor_sk']='';$r['tanggal_sk']=null;$r['username_insert']=$actor;$r['keterangan']='PPK Syamsunar sesuai instruksi 28 Oktober 2026; SK belum dilengkapi.';$id=$db->insert('pejabat_tahunan_neo',$r);$updated[]=['official_id'=>$id,'subactivity'=>$c['kd_sub_keg']];}}
$bad=$db->query('SELECT COUNT(*) n FROM kontrak_neo k LEFT JOIN pejabat_tahunan_neo p ON p.id=k.ppk_id WHERE k.kd_wilayah=? AND k.kd_opd=? AND k.tahun=? AND k.is_deleted=0 AND k.ppk_id IS NOT NULL AND (p.pegawai_id IS NULL OR p.pegawai_id<>3)',$scope)->fetch();if($bad['n'])throw new RuntimeException('PPK mismatch '.$bad['n']);
foreach($all as$c){$a=$db->query('SELECT * FROM kontrak_neo WHERE id=?',[$c['id']])->fetch();foreach($c as$k=>$v)if(!in_array($k,['ppk_id','nama_ppk','username_update','tgl_update'])&&$a[$k]!=$v)throw new RuntimeException('Contract content changed '.$k);}
$db->commit();}catch(Throwable$e){$db->rollback();throw$e;}
file_put_contents($dir.'/result.json',json_encode($updated,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo 'Updated '.count($updated).' PPK assignments; all assigned PPK verified Syamsunar; provider-less drafts resolve from annual PPK assignment; PPTK unchanged'.PHP_EOL;
